UPDATE orders o
SET order_value_original = e.expected_usd,
    order_value_usd = e.expected_usd,
    order_value_inr = e.expected_inr,
    exchange_rate_source = 'Manually corrected 2026-08-22 from user''s offline reconciliation file (invoice_details.xlsx) -- see project doc order-value-offline-file-reconciliation-2026-08-22.md'
FROM expected e
WHERE o.ref_no = e.ref_no
  AND o.order_currency = 'USD'
  AND (
    o.order_value_usd IS DISTINCT FROM e.expected_usd
    OR o.order_value_inr IS DISTINCT FROM e.expected_inr
    OR o.order_value_original IS DISTINCT FROM e.expected_usd
  );

COMMIT;

